-- =====================================================================
-- pola_truk.sql                                 disiapkan: 24 Nov 2026
--
-- PIKTOGRAM KENDARAAN PER POLA, dipanen dari katalog TBR 2026.
--
-- Tiap halaman pola di katalog menampilkan dua sampai empat siluet
-- kendaraan dengan titik MERAH (Recommendable) dan HIJAU (Available) di
-- poros-porosnya. Itu keterangan yang selama ini cuma ada di katalog
-- cetak, dan itu pula yang tercetak di artwork labelnya.
--
-- LETAKNYA TIDAK DIKETIK TANGAN. Judul pola dan legendanya dua-duanya
-- TEKS dengan koordinat di PDF katalog, dan piktogramnya selalu duduk di
-- antara keduanya -- jadi kotaknya dihitung dari dua jangkar itu lalu
-- dipangkas ke isinya. Nama polanya dikenali dari satu sifat yang tidak
-- ikut berubah: ia satu-satunya teks yang badannya lewat 30 pt.
-- 99 pola ditemukan, nol gagal.
--
-- TITIKNYA DISIMPAN SEBAGAI PECAHAN, bukan piksel: x dan y relatif
-- terhadap kotak piktogramnya sendiri, supaya tetap benar pada ukuran
-- tampil berapa pun.
--
-- YANG BELUM ADA DI SINI, dan sengaja tidak dikarang: nama poros.
-- Satu blok memuat dua sampai empat kendaraan bersebelahan, jadi x=0,2
-- berarti "seperlima dari kiri BLOK", bukan "poros kemudi". Memetakannya
-- jadi steer/drive/trailer butuh pemisahan per kendaraan, dan menebaknya
-- berarti menerbitkan keterangan posisi yang salah -- persis jenis
-- kesalahan yang tidak terlihat seperti kesalahan.
--
-- AZ675 MUNCUL DUA KALI di katalog (halaman 22 Regional, halaman 40
-- Urban). Rekomendasinya sama, tapi keduanya disimpan dan ditandai
-- kembar: kalau suatu hari dua segmen berbeda rekomendasi, itu ketahuan,
-- bukan hilang satu.
-- =====================================================================

create table if not exists public.pola_truk (
  id         uuid primary key default gen_random_uuid(),
  kode       text not null,
  hal        int  not null,
  lebar_mm   numeric,
  tinggi_mm  numeric,
  merah      int  not null default 0,
  hijau      int  not null default 0,
  kembar     boolean not null default false,
  berkas     text,
  drive_id   text,
  url_gambar text,
  titik      jsonb not null default ''[]''::jsonb,
  dibuat     timestamptz not null default now(),
  unique (kode, hal)
);

alter table public.pola_truk enable row level security;

-- Dibaca semua yang login, sama seperti pola_foto: keterangan posisi ini
-- dipakai siapa pun yang menyiapkan label.
drop policy if exists pola_truk_baca on public.pola_truk;
create policy pola_truk_baca on public.pola_truk for select using (auth.uid() is not null);

-- Ditulis hanya oleh yang boleh menulis pola foto, lewat fungsi yang sudah
-- ada -- bukan daftar peran baru yang harus diingat terpisah.
drop policy if exists pola_truk_tulis on public.pola_truk;
create policy pola_truk_tulis on public.pola_truk for all using (public.is_internal()) with check (public.is_internal());

-- GRANT DULU, BARU POLICY. Postgres memeriksa grant lebih dulu; tanpa
-- baris ini policy yang benar tidak pernah sempat dievaluasi, dan layarnya
-- menyimpulkan tabelnya kosong. Itu persis yang terjadi pada pola_foto --
-- lihat supabase/sql/pola_foto_grant_select.sql.
grant select on public.pola_truk to authenticated;

on conflict (kode,hal) do update set
  lebar_mm = excluded.lebar_mm, tinggi_mm = excluded.tinggi_mm,
  merah = excluded.merah, hijau = excluded.hijau,
  kembar = excluded.kembar, berkas = excluded.berkas, titik = excluded.titik;

